using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.Globalization;
using System.IO;
using System.Linq;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Media;
using System.Windows.Threading;
public static class V8Tests {
 static void Check(bool ok,string reason){if(!ok)throw new Exception(reason);}
 static void Layout(FrameworkElement chart,double width=900,double height=260){chart.Measure(new Size(width,height));chart.Arrange(new Rect(0,0,width,height));chart.UpdateLayout();}
 static List<ArchivePoint> Points(int count){long start=DateTime.UtcNow.AddDays(-7).Ticks;var data=new List<ArchivePoint>();for(int i=0;i<count;i++)data.Add(new ArchivePoint{T=start+i*TimeSpan.TicksPerSecond*2,Cpu=(i*13)%101,Memory=(i*7)%101,Gpu=(i*17)%101,GpuIds=new[]{"0","7"},GpuUsage=new[]{(double)((i*11)%101),(double)((i*23)%101)},Interval=2});return data;}
 static HistoryChart Dense(){var raw=Points(250000);var result=new ArchiveResult{From=raw[0].T,To=raw.Last().T,Points=raw};return new HistoryChart{From=result.From,To=result.To,HoverPoints=raw,Data=result.Plot("CPU")};}
 static string Benchmark(ResourceChart chart,Action<Point> hover,string name,int moves){Layout(chart);int baseCount=chart.BaseRebuilds,axis=chart.AxisRebuilds,gc=GC.CollectionCount(0);var times=new List<double>();for(int i=0;i<moves;i++){var clock=Stopwatch.StartNew();hover(new Point(49+(i*23)%820,100));chart.UpdateLayout();times.Add(clock.Elapsed.TotalMilliseconds);}times.Sort();Check(chart.BaseRebuilds==baseCount&&chart.AxisRebuilds==axis,"hover must not redraw chart geometry or axes");return name+" MOVES="+moves+" BASE_REDRAWS="+(chart.BaseRebuilds-baseCount)+" AXIS_REDRAWS="+(chart.AxisRebuilds-axis)+" TOTAL_MS="+times.Sum().ToString("0.000",CultureInfo.InvariantCulture)+" P50_MS="+times[moves/2].ToString("0.000",CultureInfo.InvariantCulture)+" P95_MS="+times[(int)(moves*0.95)].ToString("0.000",CultureInfo.InvariantCulture)+" GEN0="+(GC.CollectionCount(0)-gc);}
 public static int Run(string folder){folder=Path.GetFullPath(folder);Directory.CreateDirectory(folder);var app=Application.Current??new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};var log=new List<string>();var history=Dense();log.Add(Benchmark(history,history.HoverAt,"HISTORY_250K",600));var now=DateTime.UtcNow;var live=new TrendChart{Data=Enumerable.Range(0,150).Select(i=>new ResourceSample{Time=now.AddSeconds((i-150)*2),Cpu=(i*19)%101,Memory=(i*11)%101}).ToList()};log.Add(Benchmark(live,live.HoverAt,"LIVE_150",600));int draws=history.BaseRebuilds;for(int i=0;i<600;i++){history.Selected=history.From+i*(history.To-history.From)/600;history.UpdateLayout();}Check(history.BaseRebuilds==draws,"drag selection has no data redraw");log.Add("HOVER_AND_DRAG_SELECTION_DO_NOT_REDRAW_SERIES=True");
 int comparisons=0;int index=ChartHover.Nearest(history.HoverPoints,history.HoverPoints[123456].T,x=>{comparisons++;return x.T;});Check(index==123456&&comparisons<25,"binary search original samples");log.Add("HOVER_SEARCH_250K_COMPARISONS="+comparisons);
 var cache=new HistoryChart{From=now.Ticks,To=now.AddMinutes(5).Ticks,HoverPoints=new List<ArchivePoint>{new ArchivePoint{T=now.Ticks,Cpu=42,Interval=5},new ArchivePoint{T=now.AddSeconds(5).Ticks,Cpu=45,Interval=5}}};Layout(cache);cache.HoverAt(new Point(48.1,90));int layouts=cache.TooltipLayouts;for(int i=0;i<200;i++)cache.HoverAt(new Point(48.2+(i%4)/10.0,90));Check(cache.TooltipLayouts==layouts,"same sample tooltip text layout is cached");cache.HoverAt(new Point(600,90));Check(cache.HoverReading.Gap&&cache.HoverText.Contains("无有效采样"),"gap message retained");cache.ClearHover();Check(cache.HoverText=="","leave clears overlay");log.Add("SAME_SAMPLE_TOOLTIP_LAYOUT_CACHE_AND_GAPS=True");
 double velocity;double a=Motion.Damped(10,80,0,0.07,17,out velocity),b=Motion.Damped(10,80,0,0.14,17,out velocity),v=velocity,c=Motion.Damped(10,80,0,0.21,17,out velocity);Check(a>10&&a<b&&b<c&&c<80&&Math.Abs((b-a)-(c-b))>3,"meter response is nonlinear monotone damped");double afterVelocity;double atRetarget=Motion.Damped(b,20,v,0,17,out afterVelocity);Check(Math.Abs(atRetarget-b)<0.00001&&Math.Abs(v-afterVelocity)<0.00001,"retarget preserves position and velocity");Check(Motion.Ease(0)==0&&Math.Abs(Motion.Ease(1)-1)<0.00001&&Motion.Ease(0.25)>0.25,"nonlinear chart easing endpoints");log.Add("DAMPED_NONLINEAR_METER_AND_CONTINUOUS_RETARGET=True");
 var meter=new PixelMeter(10,Theme.Green,7);Layout(meter,320,7);int meterBuilds=meter.GeometryRebuilds;meter.Value=80;for(int ms=0;ms<=700;ms+=10){meter.Advance(ms);meter.UpdateLayout();}Check(meter.GeometryRebuilds==meterBuilds&&!meter.IsAnimating&&meter.DisplayValue==80,"meter frames update compositor clips without rebuilding geometry");log.Add("METER_ANIMATION_FRAMES_REBUILD_GEOMETRY=0");Check(MotionClock.ActiveCount==0,"headless motion clock idle");
 int renders=0;foreach(string theme in Theme.Keys)foreach(int width in new[]{600,1000})foreach(int dpi in new[]{96,120,192}){Theme.Apply(theme);var root=new Grid{Background=Theme.Bg};var chart=new HistoryChart{From=history.From,To=history.To,HoverPoints=history.HoverPoints,Data=history.Data,Height=260};root.Children.Add(chart);Layout(root,width,300);chart.HoverAt(new Point(width-22,100));Snapshot.Save(root,Path.Combine(folder,"hover-"+theme+"-"+width+"-"+dpi+".png"),width+48,348,dpi,null);Check(chart.HoverReading!=null,"theme size hover still present");renders++;}Theme.Apply("forest");log.Add("CACHED_CHART_THEME_SIZE_DPI_RENDERS="+renders);File.WriteAllLines(Path.Combine(folder,"v8-results.txt"),log);Console.WriteLine(string.Join("\n",log));return 0;}
 public static void Native(Application app,string folder){folder=Path.GetFullPath(folder);Directory.CreateDirectory(folder);var history=Dense();var window=new Window{Title="AQServer v8 hover pressure diagnostic",Width=1000,Height=520,Content=new Border{Background=Theme.Bg,Padding=new Thickness(24),Child=history},ShowActivated=false};app.MainWindow=window;window.Show();var timer=new DispatcherTimer(DispatcherPriority.Input){Interval=TimeSpan.FromMilliseconds(16)};int ticks=0,baseCount=0,axisCount=0,paintCount=0;var spacing=new List<double>();var clock=Stopwatch.StartNew();double previous=0;timer.Tick+=(s,e)=>{try{if(ticks==0){window.UpdateLayout();baseCount=history.BaseRebuilds;axisCount=history.AxisRebuilds;paintCount=history.HoverRepaints;previous=clock.Elapsed.TotalMilliseconds;}else{spacing.Add(clock.Elapsed.TotalMilliseconds-previous);previous=clock.Elapsed.TotalMilliseconds;}for(int i=0;i<80;i++)history.QueueHover(new Point(50+((ticks*31+i*17)%Math.Max(1,(int)history.ActualWidth-80)),80));if(++ticks<120)return;timer.Stop();history.HoverAt(new Point(history.ActualWidth/2,100));Check(history.BaseRebuilds==baseCount&&history.AxisRebuilds==axisCount,"native pointer input does not rebuild static chart");Check(history.HoverRepaints-paintCount<500,"burst mouse input is coalesced");var report=new List<string>{"SYNTHETIC_RAW_RECORDS=250000","NATIVE_POINTER_INPUT_BURST=9600","BASE_REDRAWS="+(history.BaseRebuilds-baseCount),"AXIS_REDRAWS="+(history.AxisRebuilds-axisCount),"COALESCED_HOVER_PAINTS="+(history.HoverRepaints-paintCount),"UI_TIMER_INTERVAL_P50_MS="+spacing.OrderBy(x=>x).ElementAt(spacing.Count/2).ToString("0.000",CultureInfo.InvariantCulture),"UI_TIMER_INTERVAL_MAX_MS="+spacing.Max().ToString("0.000",CultureInfo.InvariantCulture),"MOTION_CLOCK_ACTIVE="+MotionClock.ActiveCount};history.ClearHover();window.Close();Check(MotionClock.ActiveCount==0,"idle native chart has no animation loop");report.Add("IDLE_AND_HIDDEN_ANIMATION_CLOCK_STOPS=True");File.WriteAllLines(Path.Combine(folder,"native-hover-results.txt"),report);app.Shutdown();}catch(Exception error){timer.Stop();File.WriteAllText(Path.Combine(folder,"native-hover-error.txt"),error.ToString());window.Close();app.Shutdown();}};timer.Start();}
}
